<?php require __DIR__.'/../includes/bootstrap.php';if(!collector_marketplace_ready()){app_header('Collector Marketplace');?><section class="form-card"><h1>Collector Marketplace is not installed</h1><?php if((user()['role']??'')==='admin'):?><a class="button primary" href="../upgrade-collector-marketplace.php">Install Marketplace</a><?php endif?></section><?php app_footer();exit;}$q=trim($_GET['q']??'');$cat=trim($_GET['category']??'');$type=trim($_GET['type']??'');$sql="SELECT i.*,cp.shop_name,cp.slug collector_slug FROM collector_items i JOIN collector_profiles cp ON cp.id=i.collector_id WHERE i.status='active' AND cp.status='approved'";$a=[];if($q!==''){$sql.=' AND (i.title LIKE ? OR i.franchise LIKE ? OR i.description LIKE ?)';$a=array_fill(0,3,'%'.$q.'%');}if($cat!==''){$sql.=' AND i.category=?';$a[]=$cat;}if($type!==''){$sql.=' AND i.listing_type=?';$a[]=$type;}$sql.=' ORDER BY i.is_featured DESC,i.created_at DESC';$s=db()->prepare($sql);$s->execute($a);$items=$s->fetchAll();app_header('Collector Marketplace');?><section class="dashboard-hero collector-hero"><p class="eyebrow">BUY • SELL • TRADE • SHOWCASE</p><h1>Collector Marketplace</h1><p>A community marketplace for comics, cards, figures, props, autographs, and fandom treasures.</p><form class="hero-search"><input name="q" value="<?=e($q)?>" placeholder="Search collectibles or franchises"><select name="category"><option value="">All categories</option><?php foreach(collector_categories() as $k=>$v):?><option value="<?=$k?>" <?=$cat===$k?'selected':''?>><?=$v?></option><?php endforeach?></select><select name="type"><option value="">All listing types</option><?php foreach(collector_listing_types() as $k=>$v):?><option value="<?=$k?>" <?=$type===$k?'selected':''?>><?=$v?></option><?php endforeach?></select><button>Search</button></form><?php if(user()):?><p><a class="button primary" href="create.php">Open Collector Profile</a> <a class="button ghost" href="dashboard.php">My Collection</a></p><?php endif?></section><section class="collector-grid"><?php foreach($items as $i):?><article class="collector-card"><?php if($i['image_path']):?><a href="item.php?slug=<?=urlencode($i['slug'])?>"><img src="<?=e(base_url($i['image_path']))?>" alt=""></a><?php endif?><div class="collector-card-body"><p class="eyebrow"><?=e(strtoupper(collector_listing_types()[$i['listing_type']]??$i['listing_type']))?></p><h2><a href="item.php?slug=<?=urlencode($i['slug'])?>"><?=e($i['title'])?></a></h2><p><?=e($i['franchise'])?></p><p><span class="pill"><?=e(collector_categories()[$i['category']]??$i['category'])?></span> <?php if($i['condition_grade']):?><span class="pill"><?=e($i['condition_grade'])?></span><?php endif?></p><p><strong><?=$i['price']!==null?'$'.number_format((float)$i['price'],2):'Open to offers'?></strong></p><p class="muted">From <a href="view.php?slug=<?=urlencode($i['collector_slug'])?>"><?=e($i['shop_name'])?></a></p></div></article><?php endforeach?><?php if(!$items):?><div class="empty-state"><h2>No listings found</h2><p>Try another search or create the first collector listing.</p></div><?php endif?></section><?php app_footer();
